contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // send an arbitrary amount to c.go; ensure this contract has enough balance
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance");

        // observe owner's address and c balance before
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint256 cBalBefore = address(c).balance;

        // perform the call and record whether it reverted
        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after-values
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint256 cBalAfter = address(c).balance;

        // General rule: either the call reverted, or (call succeeded) owner unchanged and
        // c's balance did not increase beyond (previous balance + amount sent).
        // This captures that successful go should not make C richer than before+sent value,
        // and it preserves owner.
        assert(reverted || (ownerAfter == ownerBefore && cBalAfter <= cBalBefore + amount));
    }

    receive() external payable {}
}

